import{_ as c,C as u,o as t,c as m,a2 as d,b as o,w as a,a as r,E as n,a3 as s,j as l}from"./chunks/framework.Brv5O9VI.js";const k=JSON.parse('{"title":"F2: Regulatory Guardrailing & Out-of-Domain Filter","description":"","frontmatter":{},"headers":[],"relativePath":"features/F2-regulatory-guardrail.md","filePath":"features/F2-regulatory-guardrail.md"}'),g={name:"features/F2-regulatory-guardrail.md"};function h(p,e,f,y,A,b){const i=u("Mermaid");return t(),m("div",null,[e[4]||(e[4]=d('<h1 id="f2-regulatory-guardrailing-out-of-domain-filter" tabindex="-1">F2: Regulatory Guardrailing &amp; Out-of-Domain Filter <a class="header-anchor" href="#f2-regulatory-guardrailing-out-of-domain-filter" aria-label="Permalink to &quot;F2: Regulatory Guardrailing &amp; Out-of-Domain Filter&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p><strong>F2</strong> is the safety and domain-boundary enforcement engine of the compliance platform. Because vector search engines always return a mathematical nearest neighbor regardless of query sense, an un-guardrailed compliance system could incorrectly assign an industrial standard like <em>IS 2062 Structural Steel</em> to queries about <em>&quot;crypto token trading&quot;</em> or <em>&quot;dog food&quot;</em>. Feature F2 implements a deterministic, 4-tier regulatory guardrail in [<code>guardrail.py</code>](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/guardrail.py) that screens every prompt before audit data is generated.</p>',3)),(t(),o(s,null,{default:a(()=>[n(i,{id:"mermaid-9",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20Q%5B%22Raw%20Query%20Input%22%5D%20--%3E%20T1%7B%22Tier%201%3A%20Commercial%20Blacklist%3F%22%7D%0A%20%20%20%20T1%20--%3E%7CMatch%20Blocked%20Keyword%7C%20B1%5B%22BLOCK%3A%20Non-statutory%20commercial%20query%22%5D%0A%20%20%20%20T1%20--%3E%7CClean%7C%20T2%7B%22Tier%202%3A%20Instant%20Regex%20Pass%3F%22%7D%0A%20%20%20%20T2%20--%3E%7CMatches%20%5Cb%5Cd%7B3%2C5%7D%5Cb%20in%20standard%7C%20P1%5B%22PASS%3A%20Exact%20standard%20code%20match%22%5D%0A%20%20%20%20T2%20--%3E%7CNo%20Code%20Match%7C%20T3%7B%22Tier%203%3A%20Statutory%20Root%20Overlap%3F%22%7D%0A%20%20%20%20T3%20--%3E%7CRoot%20present%20AND%20score%20%3E%3D%200.20%7C%20P2%5B%22PASS%3A%20Statutory%20root%20matched%22%5D%0A%20%20%20%20T3%20--%3E%7CNo%20Root%7C%20T4%7B%22Tier%204%3A%20Dense%20Vector%20Threshold%3F%22%7D%0A%20%20%20%20T4%20--%3E%7CSimilarity%20%3E%3D%200.45%7C%20P3%5B%22PASS%3A%20Strong%20semantic%20alignment%22%5D%0A%20%20%20%20T4%20--%3E%7CSimilarity%20%3C%200.45%7C%20B2%5B%22BLOCK%3A%20Low%20relevance%20below%20threshold%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=d('<hr><h2 id="technical-trace-functions-involved" tabindex="-1">Technical Trace &amp; Functions Involved <a class="header-anchor" href="#technical-trace-functions-involved" aria-label="Permalink to &quot;Technical Trace &amp; Functions Involved&quot;">​</a></h2><h3 id="files-and-line-numbers" tabindex="-1">Files and Line Numbers <a class="header-anchor" href="#files-and-line-numbers" aria-label="Permalink to &quot;Files and Line Numbers&quot;">​</a></h3><ul><li><strong>Guardrail Implementation</strong>: [<code>guardrail.py:L1-L42</code>](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/guardrail.py#L1-L42)</li><li><strong>Controller Invocation</strong>: [<code>app.py:L94-L99</code>](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/app.py#L94-L99)</li><li><strong>Evaluation Suite</strong>: [<code>eval_guardrail.py:L1-L62</code>](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/eval_guardrail.py#L1-L62)</li></ul><h3 id="functions-called" tabindex="-1">Functions Called <a class="header-anchor" href="#functions-called" aria-label="Permalink to &quot;Functions Called&quot;">​</a></h3><p><code>check_domain_guardrail(query: str, matched_standard: str, similarity_score: float) -&gt; tuple[bool, str]</code>:</p><ul><li><em>Parameters</em>: <ul><li><code>query</code> (str): Raw sanitized query entered by the user.</li><li><code>matched_standard</code> (str): Target standard string resolved by FAISS (e.g., <code>&quot;IS 12269:2013&quot;</code> or <code>&quot;AIS 156&quot;</code>).</li><li><code>similarity_score</code> (float): Cosine similarity inner product value between query and standard vector ($[-1.0, 1.0]$).</li></ul></li><li><em>Return Value</em>: <ul><li><code>(True, &quot;Reason for acceptance&quot;)</code> if the query is statutory.</li><li><code>(False, &quot;Reason for rejection&quot;)</code> if the query is out-of-domain, commercial noise, or insufficiently relevant.</li></ul></li><li><em>Internal Tier Operations</em>: <ol><li><strong>Tier 1 (Explicit Commercial Blocklist)</strong>: Checks against 25+ high-frequency noise categories (cryptocurrency, trading, movies, music, social media, dining cutlery, consumer alkaline batteries, soft drinks).</li><li><strong>Tier 2 (Instant Standard Number Regex Pass)</strong>: Extracts all numerical sequences matching <code>r&#39;\\b\\d{3,5}\\b&#39;</code> in both the user query and matched standard; passes immediately if any intersection exists.</li><li><strong>Tier 3 (Statutory Root Token Matching)</strong>: Identifies domain roots (<code>water</code>, <code>bottle</code>, <code>cement</code>, <code>steel</code>, <code>rebar</code>, <code>battery</code>, <code>toy</code>, <code>kettle</code>, <code>vltd</code>, <code>tracking</code>). If a root is present and similarity score $\\ge 0.20$, the query passes.</li><li><strong>Tier 4 (Dense Semantic Similarity Threshold)</strong>: Requires a strict cosine similarity score threshold of $\\ge 0.45$ for abstract or non-keyword technical descriptions.</li></ol></li></ul><hr><h2 id="detailed-diagrams" tabindex="-1">Detailed Diagrams <a class="header-anchor" href="#detailed-diagrams" aria-label="Permalink to &quot;Detailed Diagrams&quot;">​</a></h2><h3 id="sequence-diagram" tabindex="-1">Sequence Diagram <a class="header-anchor" href="#sequence-diagram" aria-label="Permalink to &quot;Sequence Diagram&quot;">​</a></h3>',10)),(t(),o(s,null,{default:a(()=>[n(i,{id:"mermaid-115",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20autonumber%0A%20%20%20%20participant%20App%20as%20app.py%20(chat_endpoint)%0A%20%20%20%20participant%20Guard%20as%20guardrail.py%20(check_domain_guardrail)%0A%20%20%20%20participant%20Gap%20as%20gap_engine.py%0A%0A%20%20%20%20App-%3E%3EGuard%3A%20check_domain_guardrail(%22bitcoin%20wallet%22%2C%20%22IS%202062%22%2C%200.12)%0A%20%20%20%20Guard-%3E%3EGuard%3A%20Scan%20Tier%201%20Blacklist%0A%20%20%20%20Note%20over%20Guard%3A%20%22bitcoin%22%20detected%20in%20blocked_keywords%0A%20%20%20%20Guard--%3E%3EApp%3A%20(False%2C%20%22Query%20falls%20under%20non-statutory%20commercial%20category.%22)%0A%20%20%20%20App--%3E%3EApp%3A%20Early%20return%20with%20rejection%20narrative%2C%20audit_data%20%3D%20None%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=l("h3",{id:"state-diagram",tabindex:"-1"},[r("State Diagram "),l("a",{class:"header-anchor",href:"#state-diagram","aria-label":'Permalink to "State Diagram"'},"​")],-1)),(t(),o(s,null,{default:a(()=>[n(i,{id:"mermaid-119",class:"mermaid",graph:"stateDiagram-v2%0A%20%20%20%20%5B*%5D%20--%3E%20Evaluating%0A%20%20%20%20Evaluating%20--%3E%20BlockedBlacklist%3A%20Blacklisted%20term%20found%0A%20%20%20%20Evaluating%20--%3E%20PassedExactCode%3A%20Numerical%20standard%20code%20matched%0A%20%20%20%20Evaluating%20--%3E%20PassedRoot%3A%20Root%20matched%20%26%20score%20%3E%3D%200.20%0A%20%20%20%20Evaluating%20--%3E%20PassedDense%3A%20Score%20%3E%3D%200.45%0A%20%20%20%20Evaluating%20--%3E%20BlockedLowScore%3A%20Score%20%3C%200.45%0A%20%20%20%20BlockedBlacklist%20--%3E%20%5B*%5D%0A%20%20%20%20PassedExactCode%20--%3E%20%5B*%5D%0A%20%20%20%20PassedRoot%20--%3E%20%5B*%5D%0A%20%20%20%20PassedDense%20--%3E%20%5B*%5D%0A%20%20%20%20BlockedLowScore%20--%3E%20%5B*%5D%0A"})]),fallback:a(()=>[...e[2]||(e[2]=[r(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=l("h3",{id:"failure-path-diagram",tabindex:"-1"},[r("Failure Path Diagram "),l("a",{class:"header-anchor",href:"#failure-path-diagram","aria-label":'Permalink to "Failure Path Diagram"'},"​")],-1)),(t(),o(s,null,{default:a(()=>[n(i,{id:"mermaid-123",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20Input%5BQuery%20%2B%20Nearest%20FAISS%20Item%5D%20--%3E%20GuardCheck%7Bcheck_domain_guardrail()%7D%0A%20%20%20%20GuardCheck%20--%3E%7CBlocked%3A%20Blacklisted%7C%20Resp1%5B%22Return%20200%20with%20polite%20rejection%20%26%20audit_data%3A%20null%22%5D%0A%20%20%20%20GuardCheck%20--%3E%7CBlocked%3A%20Score%20%3C%200.45%7C%20Resp2%5B%22Return%20200%20with%20low-confidence%20alert%20%26%20audit_data%3A%20null%22%5D%0A%20%20%20%20GuardCheck%20--%3E%7CPassed%7C%20Continue%5B%22Proceed%20to%20Gap%20Analysis%20%26%20Audit%20Pack%20Generation%22%5D%0A"})]),fallback:a(()=>[...e[3]||(e[3]=[r(" Loading... ",-1)])]),_:1})),e[8]||(e[8]=d('<hr><h2 id="edge-cases-security-performance" tabindex="-1">Edge Cases, Security &amp; Performance <a class="header-anchor" href="#edge-cases-security-performance" aria-label="Permalink to &quot;Edge Cases, Security &amp; Performance&quot;">​</a></h2><ul><li><strong>Adversarial Noise Defense</strong>: <ul><li>Tested against 20 benchmark queries in [<code>eval_guardrail.py</code>](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/eval_guardrail.py). 100% of out-of-domain queries (e.g., &quot;Crypto token trading bot platform&quot;, &quot;Second-hand wooden office furniture&quot;, &quot;Streaming video subscription&quot;) are blocked.</li></ul></li><li><strong>True Positive Resilience</strong>: <ul><li>Colloquial compound phrases (e.g., &quot;waterbottle&quot; vs &quot;water bottle&quot;) are caught by sub-string root scanning in Tier 3, preventing false negative rejections.</li></ul></li><li><strong>Performance</strong>: <ul><li>Total guardrail execution time is under <strong>0.05 milliseconds</strong> (pure in-memory string scanning and regular expression evaluation).</li></ul></li></ul><hr><h2 id="say-it-out-loud" tabindex="-1">Say It Out Loud <a class="header-anchor" href="#say-it-out-loud" aria-label="Permalink to &quot;Say It Out Loud&quot;">​</a></h2><p>I built the Regulatory Guardrail feature to solve a classic problem with vector search: cosine similarity will always return a nearest neighbor even if the user asks something completely ridiculous like &#39;what is the price of bitcoin&#39; or &#39;give me a recipe for pizza.&#39; Without a guardrail, the system would hallucinate an official Indian Standard for unregulated goods.</p><p>In app.py, right after FAISS returns the top-matching standard and its similarity score, the query is passed into check_domain_guardrail in guardrail.py. I designed this as a four-tier filtering pipeline. In tier one, it scans against a blacklist of non-statutory commercial terms like cryptocurrency, entertainment, or dining cutlery. In tier two, if the user explicitly typed a three-to-five digit standard number like 12269 or 156, it uses a regular expression to give an instant pass. In tier three, it looks for core statutory keywords like cement, rebar, or battery; if one is present and the vector similarity is at least 0.20, it passes. Finally, in tier four, any generalized product description must clear a dense semantic similarity threshold of 0.45.</p><p>I chose this hybrid approach of rule-based regex combined with vector scoring over an LLM-based safety checker because it executes in less than a tenth of a millisecond and requires zero tokens or GPU memory. When a query fails, the backend returns a polite explanation stating that the product does not fall under statutory BIS or AIS mandates and suppresses the audit pack.</p><p>One trade-off is that very novel or emerging products that don&#39;t share our defined roots might require tuning the 0.45 similarity threshold.</p>',9))])}const q=c(g,[["render",h]]);export{k as __pageData,q as default};
